def encode_cyclic(s: str) -> str:
    """
    Encodes a string by cyclically rotating each group of three characters to the left.
    Groups with fewer than three characters remain unchanged.
    """
    def rotate_left(group: str) -> str:
        return group[1:] + group[0]

    return ''.join(
        rotate_left(s[i:i+3]) if len(s[i:i+3]) == 3 else s[i:i+3]
        for i in range(0, len(s), 3)
    )


def decode_cyclic(s: str) -> str:
    """
    Decodes a string by cyclically rotating each group of three characters to the right.
    Groups with fewer than three characters remain unchanged.
    """
    def rotate_right(group: str) -> str:
        return group[-1] + group[:-1]

    return ''.join(
        rotate_right(s[i:i+3]) if len(s[i:i+3]) == 3 else s[i:i+3]
        for i in range(0, len(s), 3)
    )
