def collatz_odd_terms ending_at_1(n):
    """
    Generate the sequence of odd terms encountered in the Collatz sequence for n,
    stopping when 1 is reached. Returns the list of odd terms in the order they appear,
    including the starting n if it's odd, and ending with 1.
    The terms are sorted in ascending order before returning.
    """
    def collatz_next(x):
        if x % 2 == 0:
            return x // 2
        else:
            return 3 * x + 1

    terms = []
    x = n
    seen = set()
    while True:
        if x % 2 == 1:
            if x not in seen:
                terms.append(x)
                seen.add(x)
        if x == 1:
            break
        x = collatz_next(x)

    # Ensure 1 is included and sort the odd terms
    if 1 not in terms:
        terms.append(1)
    return sorted(terms)

