def largest_prime_digit_sum(nums):
    """Finds the largest prime in the input list, then returns the sum of its digits."""
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    def sum_digits(n):
        return sum(int(d) for d in str(abs(n)))

    largest_prime = max(filter(is_prime, nums), default=None)
    return sum_digits(largest_prime) if largest_prime is not None else 0

